import itertools
names=[];cols=[]
for i,j,k in itertools.product(range(4),repeat=3):
    if i+j+k<=3:
        cols.append(t**i*x**j*v**k); names.append(f"t^{i}x^{j}v^{k}")
X=np.column_stack(cols)
c,_,_,_=np.linalg.lstsq(X,y,rcond=None)
r=y-X@c
print(np.mean(r**2)/np.var(y))
for n,k in zip(names,c):
    if abs(k)>0.05: print(n,round(k,4))
